  if jsonb_typeof(p_data->'progress') is not null and jsonb_typeof(p_data->'progress') <> 'array' then    raise exception 'invalid_data';  end if;  select * into lim from public.zb2_limits where id = 1;  if octet_length(p_data::text) > lim.max_bytes then raise exception 'save_too_large'; end if;   ng := coalesce((p_data->>'gold')::numeric, 0);  ns := coalesce((p_data->>'scrap')::numeric, 0);  if ng < 0 or ns < 0 then raise exception 'invalid_data'; end if;   select * into old from public.zb2_saves where user_id = u and slot = p_slot for update;   if not found then    if p_expected_revision <> 0 then raise exception 'revision_conflict'; end if;    if ng > lim.new_gold_max or ns > lim.new_scrap_max then raise exception 'limit_new_save'; end if;    for r in select (e->>'level')::integer as lvl             from jsonb_array_elements(coalesce(p_data->'progress','[]'::jsonb)) e loop      if r.lvl > lim.new_level_max then raise exception 'limit_new_save'; end if;    end loop;    insert into public.zb2_saves(user_id, slot, revision, data)    values (u, p_slot, 1, p_data) returning revision into newrev;    return newrev;  end if;   if old.revision <> p_expected_revision then raise exception 'revision_conflict'; end if;   og := coalesce((old.data->>'gold')::numeric, 0);  os := coalesce((old.data->>'scrap')::numeric, 0);  if ng - og > lim.max_gold_gain  then raise exception 'limit_gold';  end if;  if ns - os > lim.max_scrap_gain then raise exception 'limit_scrap'; end if;   for r in select e->>'id' as id, (e->>'level')::integer as lvl           from jsonb_array_elements(coalesce(p_data->'progress','[]'::jsonb)) e loop    select (oe->>'level')::integer into oldlvl    from jsonb_array_elements(coalesce(old.data->'progress','[]'::jsonb)) oe    where oe->>'id' = r.id limit 1;    if r.lvl - coalesce(oldlvl, 1) > lim.max_level_gain then raise exception 'limit_level'; end if;  end loop;   update public.zb2_saves     set data = p_data, revision = revision + 1, updated_at = now()   where user_id = u and slot = p_slot  returning revision into newrev;  return newrev;end;$$; create function public.zb2_delete_save(p_slot integer, p_expected_revision bigint)returns booleanlanguage plpgsql security definer set search_path = '' as $$declare u uuid := auth.uid(); cur bigint;begin  if u is null then raise exception 'authentication_required'; end if;  if p_slot is null or p_slot not between 1 and 3 or p_expected_revision is null then    raise exception 'invalid_request';  end if;  select revision into cur from public.zb2_saves where user_id = u and slot = p_slot for update;  if not found then return false; end if;  if cur <> p_expected_revision then raise exception 'revision_conflict'; end if;  delete from public.zb2_saves where user_id = u and slot = p_slot;  return true;end;$$; revoke all on function public.zb2_get_saves()                      from public, anon, authenticated;revoke all on function public.zb2_put_save(integer, bigint, jsonb) from public, anon, authenticated;revoke all on function public.zb2_delete_save(integer, bigint)     from public, anon, authenticated;grant execute on function public.zb2_get_saves()                      to authenticated;grant execute on function public.zb2_put_save(integer, bigint, jsonb) to authenticated;grant execute on function public.zb2_delete_save(integer, bigint)     to authenticated; commit;